import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"09 历史军事：六部天涯史论精读笔记","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/09_历史军事.md","filePath":"topics/tianya/notes/09_历史军事.md"}'),n={name:"topics/tianya/notes/09_历史军事.md"};function s(a,t,l,i,e,g){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="_09-历史军事-六部天涯史论精读笔记" tabindex="-1">09 历史军事：六部天涯史论精读笔记 <a class="header-anchor" href="#_09-历史军事-六部天涯史论精读笔记" aria-label="Permalink to &quot;09 历史军事：六部天涯史论精读笔记&quot;">​</a></h1><blockquote><p>样本：《太平洋战争》《正面抗日战场》《二战秘史》《铁血雄兵川军团》《川帮》《英雄末路》六帖（PDF 采样全文）。以下观点均出自原帖正文。</p></blockquote><h2 id="一、《太平洋战争》-青梅煮酒-1970" tabindex="-1">一、《太平洋战争》（青梅煮酒 1970） <a class="header-anchor" href="#一、《太平洋战争》-青梅煮酒-1970" aria-label="Permalink to &quot;一、《太平洋战争》（青梅煮酒 1970）&quot;">​</a></h2><p><strong>作者与年代</strong>：天涯煮酒作者&quot;青梅煮酒 1970&quot;，自述打工者、资深军迷。2015-7-15（二战胜利 70 周年）开帖，采样文本收到 2020-2，连载五年余。</p><p><strong>范围与主线</strong>：</p><ul><li>自拟五章、计划 150 万字：山雨欲来／一溃千里／绝地反击／钳形攻势／直捣黄龙。</li><li>采样可见：第一章写满明治维新、甲午（含马关谈判）、日俄战争（朴茨茅斯和约、日比谷烧打）、华盛顿会议、皇姑屯；后段已至 1944 英帕尔&quot;白骨走廊&quot;。</li><li>主线是&quot;日本如何走向太平洋战争&quot;的因果链，每战都算财政账（甲午日军费占支出 69.31%、日俄战争国债从 6 亿涨到 24 亿日元），以后勤与钱解释战场。</li></ul><p><strong>史观/视角</strong>：方法论自嘲——&quot;看完十本书说自己是专家，看完三位数后说我真的很多都不知道了&quot;，以承认无知为写作动机。少见地把战争责任下探到日本社会：评日比谷骚乱称民众&quot;所关心的只是掠夺他国的财富&quot;，&quot;这种自私、狭隘、不辩是非的极端民族主义，自然纵容了当权者更加肆无忌惮地向他国伸出掠夺之手&quot;。人物评价别致：石原莞尔&quot;智商很高，情商很低&quot;，&quot;板垣之胆、石原之谋&quot;。</p><p><strong>金句/名段</strong>：①开帖宣言&quot;人这一辈子总要干一件自己喜欢的事情吧&quot;；②英帕尔溃兵&quot;嘴上塞满野草&quot;，撤退路被日军称作&quot;白骨走廊&quot;&quot;靖国之路&quot;，再引 NHK&quot;最不负责任的战役&quot;、防卫厅战史&quot;无谋之战&quot;作结；③尼古拉二世闻对马惨败，微笑着问将军&quot;明天您想不想去打猎&quot;，半小时后拿气枪在后花园打鸟。</p><p><strong>成色</strong>：通俗演义+半考据混合。自述靠手头 180 本藏书、无条件进图书馆，但正文注明来源（路易·艾伦、日本防卫厅战史丛书、斯利姆回忆录、艾迪·鲍尔），伤亡数字分歧如实交代，属诚实的&quot;民间考据派&quot;。</p><h2 id="二、《正面抗日战场》-关河五十州" tabindex="-1">二、《正面抗日战场》（关河五十州） <a class="header-anchor" href="#二、《正面抗日战场》-关河五十州" aria-label="Permalink to &quot;二、《正面抗日战场》（关河五十州）&quot;">​</a></h2><p><strong>作者与年代</strong>：关河五十州，2009-9-6 开帖，后整理出版为《一寸河山一寸血》。帖内自述：第三部&quot;被砍了，出于可以想到的原因&quot;，才改名重写——民间史写作处境的一手证词。</p><p><strong>范围与主线</strong>：</p><ul><li>从张作霖发家写起（日俄战后日本在东北寻找代理人），经东北易帜、中东路事件，到九一八、江桥抗战（马占山），采样后段至七七事变、张自忠留平。</li><li>主线是&quot;正面战场&quot;人物史：张氏父子、蒋介石、宋哲元、张自忠、马占山皆有血肉；大量笔墨放在战前博弈（日本扶植宗社党失败后才转向张作霖、奉军兵工厂由日本专家设计）。</li></ul><p><strong>史观/视角</strong>：以江湖逻辑重写军阀史——张作霖&quot;一曰赌，二曰混，三曰搏&quot;，&quot;混不出来的叫土匪，混得出来的叫老总&quot;。为被涂抹者翻案：读者说&quot;某些人被刻意摸黑了&quot;，作者答&quot;确实有相关写作计划&quot;。写日军残暴不用空泛控诉：马占山释放 500 日俘并留声明请对方同样宽待，&quot;显然他大大高估了日军的文明程度&quot;，日军进城即杀光伤病员。</p><p><strong>金句/名段</strong>：①&quot;英雄不问出处。那年头，混不出来的叫土匪，混出来的叫老总&quot;；②九道沟子伏击后&quot;以牙还牙，以血还血，你敢杀我伤兵，我就敢灭你满门&quot;（评马占山）；③回帖&quot;在当时此地，只能选择时时从利刃的边上走过，所以才有了《一寸河山一寸血》&quot;。</p><p><strong>成色</strong>：通俗演义为主、隐含考据。白话加网络幽默（闯关东写成&quot;招生指标&quot;），但易帜时间线、中东路交涉、日俘交换等框架经得起帖内质证，属&quot;演义外壳、史实骨架&quot;。</p><h2 id="三、《二战秘史——纵论二战全史》-万国咸宁天下平" tabindex="-1">三、《二战秘史——纵论二战全史》（万国咸宁天下平） <a class="header-anchor" href="#三、《二战秘史——纵论二战全史》-万国咸宁天下平" aria-label="Permalink to &quot;三、《二战秘史——纵论二战全史》（万国咸宁天下平）&quot;">​</a></h2><p><strong>作者与年代</strong>：万国咸宁天下平（出书署名陈咸宁，《二战秘史之闪击》），2009-5-4 开帖，采样收到 2011-12 连载 447 节。自述因与人争论&quot;发现自己对于某些主流观点不太一样，甚至完全相反&quot;而写。</p><p><strong>范围与主线</strong>：</p><ul><li>只写欧洲战场：从 1919 凡尔赛宫镜厅签约、三巨头分歧、魏玛崩溃、纳粹崛起、绥靖年代，到波兰、西线、不列颠空战、巴巴罗萨，止于 1942-12 斯大林格勒解围战（&quot;冬季风暴&quot;与&quot;小土星&quot;）。</li><li>主线是&quot;凡尔赛—斯大林格勒&quot;因果链：和约&quot;没有彻底削弱也没有安抚德国&quot;，预示整个欧洲的不安定。</li><li>强调地图配图：&quot;我遭这样的罪了，所以希望大家在图片的帮助之下更直观地了解二战。&quot;</li></ul><p><strong>史观/视角</strong>：公开挑战教科书，两大论断——其一绥靖：&quot;我认为这个几近盖棺的论调是很不负责的&quot;，用英国大陆均势传统解释张伯伦们，讥其&quot;把英法两国打扮成一对被希特勒骗了糖果的天真小孩，却只字不提自己内部的勾心斗角&quot;；其二斯大林格勒：&quot;所以，斯大林格勒的神话必须破产！&quot;引朱可夫、富勒《西洋世界军事史》、梅林津《坦克战》，论证德军 8 月底尚未攻城已达进攻顶点，&quot;是希特勒硬撑着打下去的。不是红军有能力，而是元首发疯了&quot;。对德军内部也翻案：引里希特霍芬&quot;她是一个被曼斯坦因出卖的集团军&quot;，细算保卢斯突围燃料账（仅够 20 公里）。</p><p><strong>金句/名段</strong>：①德国外长签和约落泪：&quot;一个 7 千万人的民族虽灾难深重，但并没有灭亡&quot;；②贝当：&quot;这个根本不是和平条约，只是一个 20 年的停战协定&quot;；③&quot;不是红军有能力，而是元首发疯了。&quot;</p><p><strong>成色</strong>：六部中考据色彩最重。明言参考&quot;将领回忆录与解档文件&quot;，引文必署名（朱可夫、赫鲁晓夫、富勒、比弗、梅林津），读者纠错有专楼更正；缺陷是对回忆录自身的主观性未加批判。</p><h2 id="四、《铁血雄兵川军团》-关河五十州-草鞋军团-帖" tabindex="-1">四、《铁血雄兵川军团》（关河五十州，&quot;草鞋军团&quot;帖） <a class="header-anchor" href="#四、《铁血雄兵川军团》-关河五十州-草鞋军团-帖" aria-label="Permalink to &quot;四、《铁血雄兵川军团》（关河五十州，&quot;草鞋军团&quot;帖）&quot;">​</a></h2><p><strong>作者与年代</strong>：关河五十州，2012-4-25 开帖，采样收到 2013-9 第 563 节，与其《正面抗日战场》互为姊妹篇。</p><p><strong>范围与主线</strong>：</p><ul><li>上半部四川军阀史：熊克武东渡学军、泸州成都广安历次起义失败（总结&quot;新军指挥权在官府、会党靠不住&quot;两条教训），到刘湘、杨森、刘文辉的防区混战。</li><li>下半部出川抗战：杨森二十军淞沪血战、三次长沙会战（二十军追击、王陵基三十集团军）、1944 桂柳会战（采样末段）。</li><li>主线是&quot;救赎&quot;：一支打了几十年内战、穿草鞋的杂牌军在民族战争中洗刷名声。</li></ul><p><strong>史观/视角</strong>：不神化不丑化军阀——杨森&quot;崇洋&quot;到禁止子女碰胡琴（&quot;瞎子算命要饭的东西&quot;）、&quot;老婆成排，儿女成连&quot;、分枪&quot;食言自肥&quot;打参谋长耳光。用&quot;配角/主角&quot;框架重估战绩：长沙后&quot;第二十军在国内的声名达到巅峰&quot;，又点破王陵基部&quot;差不差，还得看跟谁比&quot;。用人际结构解释战场失利：海竞强师因是白崇禧外甥部队，柳州外围&quot;杳无音讯&quot;。</p><p><strong>金句/名段</strong>：①宋美龄广播：&quot;中国只有断头的将军，没有投降的将军，守长沙的王超奎就是例子&quot;，赴美时再说&quot;像王超奎这样战至最后一弹、最后一人，在中国士兵中是极寻常的&quot;；②引伦敦报道&quot;际此远东阴雾密布中，惟长沙天空之云彩确见光辉夺目&quot;；③王陵基自白&quot;打了一辈子内战，若不参加这次的抗战，实在愧为军人&quot;，又叹韩全朴&quot;不用他，我又能用谁呢&quot;——杂牌军人事困局一笔写尽。</p><p><strong>成色</strong>：通俗演义+混合。中日双方战史细节（序列、师团动向）见功夫，但人物轶事多采传闻不注史源，&quot;七分史料三分演义&quot;。</p><h2 id="五、《川帮-原川帮太和-已出版-》-至死已末" tabindex="-1">五、《川帮（原川帮太和，已出版）》（至死已末） <a class="header-anchor" href="#五、《川帮-原川帮太和-已出版-》-至死已末" aria-label="Permalink to &quot;五、《川帮（原川帮太和，已出版）》（至死已末）&quot;">​</a></h2><p><strong>作者与年代</strong>：至死已末，80 后，2009-3 开帖，已出版。先纠正归类：此帖不是军事史，而是四川江湖/黑帮纪实型传奇，是&quot;川军团&quot;之外的袍哥文化当代余脉。</p><p><strong>范围与主线</strong>：</p><ul><li>双层结构：外层是作者 1999 年的高中岁月（被古惑仔电影塑造的英雄观、与 18 岁被判死刑的&quot;杂皮&quot;肖三的鸽子血文身之约）；内层是&quot;卫国叔叔&quot;陈卫国口述发迹史。</li><li>核心&quot;太和生意&quot;：&quot;一句话，就是买卖古董而已&quot;——下乡收祖传金银玉器，十倍百倍销往省城、广州、香港；帮派由文物贩子起家、建堂口、扩至云南，盛极而散。</li><li>后段收于悲剧：老六携双管猎枪的灭门之夜（长林以身为门而死）、陈父病危、父子十年隔阂在病房和解。</li></ul><p><strong>史观/视角</strong>：开宗明义的自省：&quot;大家尽量把这个当故事看吧……能不能百分之百的真实，我不能保证。只是希望看过之后，大家能有一些思考，那所谓风光的背后，有多少的罪恶，和要付出多大的代价。&quot;以&quot;血性&quot;释川人：&quot;穿上军装就是最强的军人，脱下军装就是最悍的土匪。&quot;罕见写出文物劫难的社会史：太和生意&quot;只盯金银玉，连瓷器都看不上&quot;，晚年陈卫国自陈&quot;我们做那个生意简直是在作孽……这是不可原谅的罪恶！所以我后来坐牢了，也是活该！&quot;</p><p><strong>金句/名段</strong>：①长林&quot;最后一个念头是，明天的早饭该谁去做？&quot;；②肖三偷鸽子、花 10 块钱买酒给兄弟文身，&quot;这哪儿像是一个杂皮能有的笑容？倒像是中国的劳动人民，那种有了收获之后的笑&quot;；③&quot;谁拿了保护费就能保你全家平安无事的，谁就是好同志。&quot;（与关河写张作霖互证乱世秩序观）</p><p><strong>成色</strong>：文学创作/纪实混合，非史论。价值在证词：为八九十年代基层中国留下收古董、拜把子、堂口经济的民间底稿，细节不可当信史。</p><h2 id="六、《英雄末路-历史上那些大人物之死》-鼎湖听泉" tabindex="-1">六、《英雄末路：历史上那些大人物之死》（鼎湖听泉） <a class="header-anchor" href="#六、《英雄末路-历史上那些大人物之死》-鼎湖听泉" aria-label="Permalink to &quot;六、《英雄末路：历史上那些大人物之死》（鼎湖听泉）&quot;">​</a></h2><p><strong>作者与年代</strong>：鼎湖听泉，2019-4-18 开帖，采样收到 2019-10，已写二十六篇，天涯后期煮酒的代表文体。</p><p><strong>范围与主线</strong>：</p><ul><li>切口唯一：大人物的&quot;死&quot;——秦始皇是否被赵高所杀、项羽五马分尸、刘邦驾崩四日吕后秘不发丧、吕后被苍狗吓死、七国之乱起于棋盘血案、周亚夫&quot;自杀与被自杀&quot;、霍去病射杀李敢、巫蛊之祸、钩弋夫人&quot;立子杀母&quot;、汉成帝暴毙温柔乡、汉哀帝与董贤。</li><li>实际以&quot;死亡悬案&quot;为索引串起秦末至西汉末三百年政治史，每次非正常死亡都是一场权力斗争的切片。</li></ul><p><strong>史观/视角</strong>：明示方法论是&quot;合理怀疑+多元猜想&quot;：&quot;秦始皇之死演化出了万千可能……这正是历史的最大魅力。&quot;提供的是嫌疑人、动机与证据链（赵高作为最大受益者有&quot;杀死老板秦始皇的最大嫌疑或动机，是头号弑君者&quot;）。去浪漫化立场：写垓下不写悲剧英雄，写项羽&quot;首先是一个政治人……舍大家而顾小家，这是典型的小家子气&quot;&quot;哭得太早&quot;。</p><p><strong>金句/名段</strong>：①&quot;历史上的那些大人物之死，很多都是死得蹊跷……原本透明度不高的深宫呈现的也大都是鬼影幢幢之影像&quot;；②读太史公&quot;七月丙寅，始皇崩于沙丘平台&quot;十二字：&quot;看来也是对他的死颇感迷茫，对此中委曲不敢妄言&quot;；③评赵氏姐妹&quot;贪图享乐的结果，也只能是来得快去得也快，反误了卿卿性命&quot;。</p><p><strong>成色</strong>：通俗史话，考据最弱。骨架本《史记》《资治通鉴》，推理常以&quot;据说&quot;&quot;某些历史研究者分析&quot;引入，野史正史混编；价值在普及与启发。</p><h2 id="总览与心得-这批民间史论的价值与局限" tabindex="-1">总览与心得：这批民间史论的价值与局限 <a class="header-anchor" href="#总览与心得-这批民间史论的价值与局限" aria-label="Permalink to &quot;总览与心得：这批民间史论的价值与局限&quot;">​</a></h2><p><strong>价值</strong>：</p><ol><li><strong>视角补偿</strong>。六部作品共同对抗&quot;课本化&quot;历史：青梅煮酒把战争责任追到日本社会各层，关河五十州为张作霖、马占山、王陵基恢复复杂性，万国咸宁天下平直接宣布&quot;斯大林格勒的神话必须破产&quot;。民间写作最大的本钱就是没有结论包袱。</li><li><strong>写作伦理自觉</strong>。作者们公开交代资料与不确定性：青梅煮酒列书单并注明取舍，万国咸宁天下平引文署名，至死已末声明&quot;不能保证百分之百真实&quot;。&quot;明牌的演义&quot;比冒充定论的写作更可信。</li><li><strong>连载即共治</strong>。四部长篇都有活跃纠错互动，读者质证—作者更正构成民间同行评审；关河帖子被&quot;砍&quot;的自述，忠实记录了民间史写作的空间边界。</li><li><strong>风格即桥梁</strong>。从&quot;翠花看茶&quot;到&quot;皇家豪华自驾游&quot;，戏谑语体把大部头史事送给了不进图书馆的读者，是学院写作做不到的传播功。</li></ol><p><strong>局限</strong>：</p><ol><li><strong>史源单一</strong>。二战秘史全靠将领回忆录——恰是自我辩护最强的文体；川军团的轶事、英雄末路的&quot;据说&quot;基本无注。</li><li><strong>翻案冲动过头</strong>。从&quot;神话必须破产&quot;到&quot;头号弑君者&quot;，民间史论爱把复杂因果压成一个惊人反命题，破除一个脸谱有时是竖起另一个。</li><li><strong>虚构与史实边界模糊</strong>。川帮一类被归入&quot;历史&quot;栏目，读者易把小说当史料；用前须分清演义、证词、考据三层。</li><li><strong>未完成率高</strong>。太平洋战争五年才写到第四章，二战秘史止步 447 节，正面战场第三部被砍——民间史论几乎都烂尾或夭折，须按&quot;断代样本&quot;对待。</li></ol><p>一句话：这批天涯史论是中文互联网的&quot;平民国史馆&quot;——史料未必最硬，但它保存了学院叙事之外的同情、怀疑与体温。</p>',50)])])}const d=o(n,[["render",s]]);export{h as __pageData,d as default};
